const lv_img_dsc_t *TbtIcon(uint8_t icon_id) {
    switch (icon_id) {
        case TBT_ICON_STRAIGHT: return &tbt_icon_straight;
        case TBT_ICON_TURN_LEFT: return &tbt_icon_turn_left;
        case TBT_ICON_TURN_RIGHT: return &tbt_icon_turn_right;
        case TBT_ICON_SLIGHT_LEFT: return &tbt_icon_slight_left;
        case TBT_ICON_SLIGHT_RIGHT: return &tbt_icon_slight_right;
        case TBT_ICON_SHARP_LEFT: return &tbt_icon_sharp_left;
        case TBT_ICON_SHARP_RIGHT: return &tbt_icon_sharp_right;
        case TBT_ICON_UTURN: return &tbt_icon_uturn;
        case TBT_ICON_ROUNDABOUT: return &tbt_icon_roundabout;
        case TBT_ICON_ARRIVE: return &tbt_icon_arrive;
        case TBT_ICON_NONE:
        default: return &tbt_icon_straight;
    }
}
